      var rv = Core.ledger.saleRevenue(s, state.products), un = Core.ledger.uncollectedFor(s, state, ix.paid);
      groups[cat].revenue += rv; groups[cat].uncollected += un;
      var ci = Core.ledger.saleCostInfo(s, state);
