    var start = isIso(sale.Covers_From) ? sale.Covers_From
      : U().addCycle(end, -(Number(sale.Months) || 1), cycleOf(L().productOf(products, sale.Product_ID)));
    if (!(start < end)) start = U().isoAddDays(end, -1);
