/** Runs in the customer's browser. Builds the page from the JSON block with textContent only, so nothing is parsed as markup. */
function payClient_() {
  var D = JSON.parse(document.getElementById('pay-data').textContent);
  var app = document.getElementById('app');
  var T = D.t;
  var NUM = /^(\+?88)?01\d{9}$/;
  var BASE = location.pathname.replace(/\/$/, '');
  // Poll gaps in ms: 5s, 10s, 20s, then 30s for good. A stage change or a user action starts the schedule again from 5s.
  var POLL = [5000, 10000, 20000, 30000];
  var saved = ''; try { saved = localStorage.getItem('payLang') || ''; } catch (e) {}
  if ((saved === 'en' || saved === 'bn') && D.all[saved]) { D.lang = saved; T = D.all[saved]; }
  var st = { lang: D.lang, method: D.intent ? D.intent.method : '', intent: D.intent, status: D.status, until: D.until, number: D.intent ? D.intent.number : '', trx: D.intent ? D.intent.trx : '', err: '', busy: false, editNumber: false,
    rcpt: null, rcptBusy: false, rcptTries: 0, rcptFail: false, seenAt: '' };
  var skew = D.now ? D.now - Date.now() : 0;
  var step = 0, pollTimer = null, tickTimer = null, cdEl = null, expPolled = false, etag = '';

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined && text !== null) n.textContent = text;
    return n;
  }
  function fill(s, vars) { return String(s).replace(/\{(\w+)\}/g, function (m, k) { return vars && vars[k] !== undefined ? vars[k] : m; }); }
  function method(id) { for (var i = 0; i < D.methods.length; i++) if (D.methods[i].id === id) return D.methods[i]; return null; }
  function day(iso) {
    var d = new Date(String(iso).slice(0, 10) + 'T00:00');
    return isNaN(d) ? iso : d.toLocaleDateString(st.lang === 'bn' ? 'bn-BD' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
  }
  function money(n) { return '৳' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
  function stage() { return st.status.stage; }
  function closed() { return stage() === 'expired' || stage() === 'cancelled'; }

  function copyText(value, done) {
    function fallback() {
      var a = document.createElement('textarea'); a.value = String(value); a.readOnly = true; a.className = 'offscreen';
      document.body.appendChild(a); a.select(); try { if (document.execCommand('copy')) done(); } catch (e) {} a.remove();
    }
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(String(value)).then(done, fallback);
    else fallback();
  }
  function copyBtn(value, label) {
    var b = el('button', 'cp', label || T.copy);
    b.type = 'button';
    b.addEventListener('click', function () {
      copyText(value, function () { b.textContent = T.copied; b.classList.add('done'); setTimeout(function () { b.textContent = label || T.copy; b.classList.remove('done'); }, 1500); });
    });
    return b;
  }

  // ---- countdown ----
  function remaining() { return D.expires ? Date.parse(D.expires) - (Date.now() + skew) : NaN; }
  function clock(ms) {
    var s = Math.max(0, Math.floor(ms / 1000)), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
    return h > 0 ? h + T.cdH + ' ' + m + T.cdM : m + T.cdM + ' ' + (s % 60) + T.cdS;
  }
  function tick() {
    if (!cdEl) return;
    var left = remaining();
    if (isNaN(left)) return;
    if (left <= 0) { cdEl.textContent = T.expiresSoon; cdEl.className = 'cd soon'; if (!closed() && !expPolled) { expPolled = true; poll(); } return; }
    cdEl.textContent = fill(T.expiresIn, { time: clock(left) });
    cdEl.className = 'cd' + (left < 600000 ? ' soon' : '');
  }

  // ---- cards ----
  function langBar() {
    var bar = el('div', 'bar np');
    var g = el('div', 'lang'); g.setAttribute('role', 'group'); g.setAttribute('aria-label', T.language);
    [['en', 'English'], ['bn', 'বাংলা']].forEach(function (l) {
      var b = el('button', '', l[1]); b.type = 'button'; b.id = 'lang-' + l[0]; b.lang = l[0]; b.setAttribute('aria-pressed', String(st.lang === l[0]));
      b.addEventListener('click', function () { setLang(l[0]); });
      g.appendChild(b);
    });
    bar.appendChild(g);
    return bar;
  }

  function summary() {
    var c = el('div', 'card');
    var top = el('header', 'top');
    top.appendChild(el('h1', '', D.title));
    var who = D.kind === 'sale' ? [D.customerName, T.plan].filter(Boolean).join(' · ') : D.customerName;
    if (who) top.appendChild(el('p', 'who', who));
    c.appendChild(top);
    var amt = el('div', 'amt');
    amt.appendChild(el('span', 'v', money(D.amount)));
    var inv = el('span', 'inv', T.ref); inv.appendChild(el('b', '', D.ref));
    amt.appendChild(inv);
    c.appendChild(amt);
    cdEl = null;
    if (D.kind === 'request' && D.expires && (stage() === 'created' || stage() === 'waiting' || stage() === 'claimed')) {
      cdEl = el('p', 'cd'); cdEl.id = 'countdown';
      c.appendChild(cdEl);
      tick();
    } else c.appendChild(el('div', 'cd'));
    return c;
  }

  function stageIndex(s) { return { created: 0, waiting: 1, claimed: 1, received: 2, confirmed: 3 }[s] || 0; }

  function status() {
    var c = el('div', 'card np');
    var ol = el('ol', 'track');
    var s = stage();
    if (closed()) {
      var first = el('li', 'done', T.t0);
      var last = el('li', 'bad', s === 'expired' ? T.tExpired : T.tCancelled); last.setAttribute('aria-current', 'step');
      ol.appendChild(first); ol.appendChild(last);
    } else {
      var idx = stageIndex(s);
      ['t0', 't1', 't2', 't3'].forEach(function (k, i) {
        var li = el('li', i < idx || s === 'confirmed' ? 'done' : i === idx ? 'cur' : '', T[k]);
        if (i === idx && s !== 'confirmed') li.setAttribute('aria-current', 'step');
        ol.appendChild(li);
      });
    }
    c.appendChild(ol);
    var m = method(st.intent ? st.intent.method : '');
    var manual = !!m && !m.auto;
    var text = { created: T.m0, waiting: m ? (manual ? T.m1m : fill(T.m1, { method: m.label })) : T.m1b, claimed: manual ? T.m1cm : T.m1c, received: T.m2, confirmed: T.m3, expired: T.mExpired, cancelled: T.mCancelled }[s] || T.m0;
    var box = el('div', 'msg' + (s === 'confirmed' ? ' ok' : closed() ? ' bad' : ''), text);
    box.setAttribute('role', 'status');
    if (s === 'confirmed' && st.until) box.appendChild(el('span', 'sub', fill(T.until, { date: day(st.until) })));
    c.appendChild(box);
    return c;
  }

  function chooser() {
    var sec = el('section', 'card block np');
    sec.appendChild(el('h2', '', T.chooseTitle));
    sec.appendChild(el('p', 'hint', T.chooseHint));
    var grid = el('div', 'grid');
    D.methods.forEach(function (m) {
      var b = el('button', 'tile m-' + m.id);
      b.type = 'button';
      b.setAttribute('aria-pressed', String(st.method === m.id));
      b.disabled = !m.ready;
      if (D.logos[m.id]) { var lg = el('span', 'logo'); var li = el('img'); li.src = D.logos[m.id]; li.alt = ''; li.draggable = false; lg.appendChild(li); b.appendChild(lg); }
      else b.appendChild(el('span', 'dot'));
      b.appendChild(el('span', 'nm', m.label));
      if (!m.ready) b.appendChild(el('span', 'sm', T.notReady));
      b.addEventListener('click', function () { st.method = m.id; st.err = ''; st.editNumber = !(st.intent && st.intent.method === m.id); render(); });
      grid.appendChild(b);
    });
    sec.appendChild(grid);
    return sec;
  }

  function numberForm(m) {
    var body = el('div', 'pbody');
    body.appendChild(el('h3', '', m.id === 'bank' ? T.numberTitleBank : fill(T.numberTitle, { method: m.label })));
    body.appendChild(el('p', 'hint', T.numberHint));
    var lab = el('label', '', T.numberLabel); lab.setAttribute('for', 'num');
    var inp = el('input'); inp.id = 'num'; inp.type = 'tel'; inp.inputMode = 'numeric'; inp.autocomplete = 'tel'; inp.placeholder = T.numberPlaceholder; inp.value = st.number;
    inp.addEventListener('input', function () { st.number = inp.value; });
    body.appendChild(lab); body.appendChild(inp);
    if (st.err) { var e = el('div', 'err', st.err); e.setAttribute('role', 'alert'); body.appendChild(e); }
    var go = el('button', 'btn', st.busy ? T.saving : T.next); go.type = 'button'; go.disabled = st.busy;
    go.addEventListener('click', function () {
      if (!NUM.test(String(st.number).replace(/[\s-]/g, ''))) { st.err = T.badNumber; render(); return; }
      save({ method: st.method, number: st.number, claimed: false, trx: '' });
    });
    inp.addEventListener('keydown', function (ev) { if (ev.key === 'Enter') go.click(); });
    body.appendChild(go);
    return body;
  }

  function stepsFor(m) {
    var body = el('div', 'pbody');
    body.appendChild(el('h3', '', T.stepsTitle));
    if (m.id === 'bank') {
      if (!m.ready) { body.appendChild(el('div', 'warn', T.bNoAccount)); return body; }
      body.appendChild(el('p', 'hint', T.bOpen));
      var kv = el('dl', 'kv');
      [[T.bBank, m.bankName], [T.bName, m.accountName], [T.bNumber, m.accountNumber, true], [T.bBranch, m.branch], [T.bRouting, m.routing, true], [T.bAmount, money(D.amount), D.amount], [T.bRef, D.ref, true]].forEach(function (r) {
        if (!r[1]) return;
        var row = el('div'); var dt = el('dt', '', r[0]); var dd = el('dd', r[2] ? 'mono' : '', String(r[1]));
        row.appendChild(dt); row.appendChild(dd);
        if (r[2]) row.appendChild(copyBtn(r[2] === true ? r[1] : r[2]));
        kv.appendChild(row);
      });
      body.appendChild(kv);
      if (m.note) body.appendChild(el('p', 'note', m.note));
      body.appendChild(el('p', 'note', T.bSlow));
      return body;
    }
    if (!m.ready) { body.appendChild(el('div', 'warn', fill(T.wNoNumber, { method: m.label }))); return body; }
    var ol = el('ol', 'steps');
    function item(label, big, copyVal) {
      var li = el('li'); var tx = el('div', 'tx'); tx.appendChild(document.createTextNode(label));
      if (big) tx.appendChild(el('span', 'big mono', big));
      li.appendChild(tx);
      if (copyVal !== undefined) li.appendChild(copyBtn(copyVal));
      ol.appendChild(li);
    }
    item(fill(T.wOpen, { method: m.label }));
    item(T.wTo, m.number, m.number);
    item(T.wAmount, money(D.amount), D.amount);
    item(T.wRef, D.ref, D.ref);
    item(m.auto ? T.wPin : T.wPinManual);
    body.appendChild(ol);
    body.appendChild(el('p', 'note', m.auto ? T.autoNote : T.manualNote));
    return body;
  }

  function claimBox() {
    var box = el('div', 'claim');
    box.appendChild(el('h3', '', T.claimTitle));
    var cm = method(st.intent.method);
    var manual = !!cm && !cm.auto;
    var lab = el('label', '', manual ? T.trxLabelReq : T.trxLabel); lab.setAttribute('for', 'trx');
    var inp = el('input'); inp.id = 'trx'; inp.autocomplete = 'off'; inp.value = st.trx; inp.maxLength = 40;
    box.appendChild(lab); box.appendChild(inp); box.appendChild(el('p', 'hint', manual ? T.trxHintReq : T.trxHint));
    if (st.err) { var e = el('div', 'err', st.err); e.setAttribute('role', 'alert'); box.appendChild(e); }
    var done = st.intent && st.intent.claimed;
    var b = el('button', manual ? 'btn' : 'btn alt', done ? T.claimed : T.claim); b.type = 'button'; b.disabled = st.busy || !!done || (manual && !String(st.trx).trim());
    inp.addEventListener('input', function () { st.trx = inp.value; if (manual) b.disabled = st.busy || !!done || !String(st.trx).trim(); });
    b.addEventListener('click', function () { save({ method: st.intent.method, number: st.intent.number, claimed: true, trx: st.trx }); });
    box.appendChild(b);
    return box;
  }

  function panel() {
    var m = method(st.method);
    if (!m) return null;
    var p = el('div', 'card panel np m-' + m.id);
    var band = el('div', 'band'); band.appendChild(el('span', '', m.label));
    if (st.intent && st.intent.method === m.id && !st.editNumber) {
      var ch = el('button', '', T.editNumber); ch.type = 'button';
      ch.addEventListener('click', function () { st.editNumber = true; st.err = ''; render(); });
      band.appendChild(ch);
    }
    p.appendChild(band);
    var needsNumber = !(st.intent && st.intent.method === m.id) || st.editNumber;
    if (needsNumber) { p.appendChild(numberForm(m)); return p; }
    var from = el('div', 'pbody'); from.appendChild(el('p', 'hint', T.paidFrom + ': ' + st.intent.number));
    p.appendChild(from);
    p.appendChild(stepsFor(m));
    if (m.ready && stage() !== 'received' && stage() !== 'confirmed') { var cb = el('div', 'pbody'); cb.appendChild(claimBox()); p.appendChild(cb); }
    return p;
  }

  // ---- receipt and delivery ----
  function paidAt() {
    var rows = st.status.rows || [];
    var loc = st.lang === 'bn' ? 'bn-BD' : 'en-GB';
    for (var i = rows.length - 1; i >= 0; i--) if (rows[i].date) {
      var raw = String(rows[i].date), d = new Date(raw.replace(' ', 'T'));
      if (isNaN(d)) return raw;
      return /\d[T ]\d/.test(raw) ? d.toLocaleString(loc, { dateStyle: 'medium', timeStyle: 'short' }) : d.toLocaleDateString(loc, { dateStyle: 'medium' });
    }
    return st.seenAt ? new Date(st.seenAt).toLocaleString(loc, { dateStyle: 'medium', timeStyle: 'short' }) : '';
  }
  function receiptLines() {
    var m = method(st.intent ? st.intent.method : st.status.method || '');
    var lines = [[T.rRef, D.ref, true], [T.rAmount, money(D.amount)]];
    if (m) lines.push([T.rMethod, m.label]);
    if (st.intent && st.intent.trx) lines.push([T.rTrx, st.intent.trx, true]);
    var when = paidAt();
    if (when) lines.push([T.rTime, when]);
    return lines;
  }
  function receiptCard() {
    var c = el('div', 'card rc');
    c.appendChild(el('h2', '', T.rTitle));
    var lines = receiptLines();
    var kv = el('dl', 'kv');
    lines.forEach(function (l) { var row = el('div'); row.appendChild(el('dt', '', l[0])); row.appendChild(el('dd', l[2] ? 'mono' : '', String(l[1]))); kv.appendChild(row); });
    c.appendChild(kv);
    var acts = el('div', 'acts np');
    var plain = [D.title, ''].concat(lines.map(function (l) { return l[0] + ': ' + l[1]; })).join('\n');
    var cp = copyBtn(plain, T.rCopy); cp.className = 'btn'; acts.appendChild(cp);
    var pr = el('button', 'btn', T.rPrint); pr.type = 'button'; pr.addEventListener('click', function () { window.print(); });
    acts.appendChild(pr);
    c.appendChild(acts);
    return c;
  }
  function wantsOrder() { return D.kind === 'request' && stage() === 'confirmed'; }
  function deliveredCard() {
    var c = el('div', 'card rc');
    c.appendChild(el('h2', '', T.dTitle));
    var dl = st.status.delivery;
    var r = st.rcpt;
    // A custom link with nothing to deliver and no terms or review links has nothing to say here.
    if (r && !r.code && dl === '' && !r.tos && !(r.links && r.links.length)) return null;
    if (r && r.code) {
      c.appendChild(el('p', 'hint', T.dCode));
      var code = el('div', 'code'); code.appendChild(el('span', 'val', r.code)); code.appendChild(copyBtn(r.code));
      c.appendChild(code);
    } else if (dl === 'failed') {
      c.appendChild(el('div', 'warn', T.dFailed));
    } else if (dl === 'pending') {
      c.appendChild(el('div', 'msg ok', T.dPending));
    } else if (dl === 'delivered') {
      c.appendChild(el('div', 'msg ok', r ? T.dDelivered : st.rcptFail ? T.dRetry : T.dLoading));
    } else if (!r) {
      c.appendChild(el('div', 'msg', st.rcptFail ? T.dRetry : T.dLoading));
    }
    if (r && r.tos) { var tos = el('div', 'tos'); tos.appendChild(el('b', '', T.dTos)); tos.appendChild(document.createTextNode(r.tos)); c.appendChild(tos); }
    var links = ((r && r.links) || []).filter(function (l) { return l && typeof l.url === 'string' && l.url.indexOf('https://') === 0; });
    if (links.length) {
      c.appendChild(el('p', 'rv', T.dReview));
      var box = el('div', 'links np');
      links.forEach(function (l) {
        var a = el('a', 'btn', l.label === 'Discord' ? T.dDiscord : l.label === 'Facebook' ? T.dFacebook : String(l.label || ''));
        a.href = l.url; a.rel = 'noopener noreferrer'; a.target = '_blank';
        box.appendChild(a);
      });
      c.appendChild(box);
    }
    return c;
  }

  function render() {
    var active = document.activeElement && document.activeElement.id;
    app.textContent = '';
    document.documentElement.lang = st.lang;
    app.appendChild(langBar());
    app.appendChild(summary());
    app.appendChild(status());
    if (stage() === 'confirmed') {
      app.appendChild(receiptCard());
      if (wantsOrder()) { var dc = deliveredCard(); if (dc) app.appendChild(dc); }
    } else if (!closed()) {
      app.appendChild(chooser());
      var p = panel();
      if (p) app.appendChild(p);
    }
    app.appendChild(el('footer', 'foot np', T.secure));
    if (active) { var back = document.getElementById(active); if (back) back.focus(); }
  }

  function setLang(l) {
    if (l === st.lang || !D.all[l]) return;
    st.lang = l; T = D.all[l];
    try { localStorage.setItem('payLang', l); } catch (e) {}
    render();
  }

  // ---- network ----
  // The server says only 'closed' for a Paid or Cancelled link; the last polled stage tells which. Unknown stage gets a neutral text.
  function closedText() {
    var sg = st.status && st.status.stage;
    return sg === 'confirmed' ? T.m3 : sg === 'cancelled' ? T.mCancelled : T.mClosed;
  }
  function save(body) {
    st.busy = true; st.err = ''; etag = ''; render();
    fetch(BASE + '/intent', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        st.busy = false;
        if (!d || !d.ok) {
          var why = String((d && d.error) || '');
          st.err = /expired/i.test(why) ? T.mExpired : /closed/i.test(why) ? closedText() : /cancel/i.test(why) ? T.mCancelled : why || T.failed;
          render(); step = 0; poll(); return;
        }
        st.intent = d.intent; st.status = { stage: d.status.stage, rows: d.status.rows, delivery: st.status.delivery || '', method: d.intent.method }; st.until = d.until || st.until; st.method = d.intent.method; st.number = d.intent.number; st.editNumber = false;
        render(); restart();
      })
      .catch(function () { st.busy = false; st.err = T.failed; render(); });
  }

  // Fetch the receipt once the order is confirmed: it carries the terms, the review links and, when a code was delivered, the code.
  // Again only if the code was not there yet and delivery has since become 'delivered'. At most four tries in all.
  function loadReceipt() {
    if (!wantsOrder() || st.rcptBusy || st.rcptTries >= 4) return;
    var needCode = st.status.delivery === 'delivered' && !(st.rcpt && st.rcpt.code);
    if (st.rcpt && !needCode) return;
    if (st.rcpt && st.rcpt.codeTried) return;
    st.rcptBusy = true; st.rcptTries++;
    fetch(BASE + '/receipt', { cache: 'no-store' }).then(function (r) { return r.ok ? r.json() : null; }).then(function (d) {
      st.rcptBusy = false;
      if (!d || !Array.isArray(d.lines)) { st.rcptFail = true; render(); return; }
      st.rcptFail = false;
      st.rcpt = { code: typeof d.code === 'string' ? d.code : '', tos: typeof d.tos === 'string' ? d.tos : '', links: Array.isArray(d.links) ? d.links : [], codeTried: st.status.delivery === 'delivered' };
      render();
    }).catch(function () { st.rcptBusy = false; st.rcptFail = true; render(); });
  }

  function settled() {
    var s = stage();
    if (s === 'expired' || s === 'cancelled') return true;
    if (s !== 'confirmed') return false;
    if (D.kind !== 'request') return true;
    var dl = st.status.delivery;
    if (!st.rcpt && st.rcptTries < 4) return false;
    if (dl === 'delivered') return !!(st.rcpt && (st.rcpt.code || st.rcpt.codeTried)) || st.rcptTries >= 4;
    return dl === '';
  }

  function schedule() {
    clearTimeout(pollTimer); pollTimer = null;
    if (document.hidden || settled()) return;
    pollTimer = setTimeout(poll, POLL[Math.min(step, POLL.length - 1)]);
  }
  function restart() { step = 0; schedule(); }

  // The poll sends the ETag of the last answer. 304 means unchanged: back off as for an unchanged answer, never an error.
  // A network error or a bad answer also backs off and the loop goes on: schedule() runs in every case.
  function poll() {
    clearTimeout(pollTimer); pollTimer = null;
    fetch(BASE + '/status', { cache: 'no-store', headers: etag ? { 'If-None-Match': etag } : {} }).then(function (r) {
      if (r.status === 304) return { unchanged: true };
      var tag = r.headers.get('ETag'); if (tag) etag = tag;
      return r.json();
    }).then(function (d) {
      if (d && d.unchanged) { step++; loadReceipt(); return; }
      if (!d || !d.ok) { step++; return; }
      var changed = d.stage !== stage() || (d.delivery || '') !== (st.status.delivery || '');
      if (changed) {
        if (d.stage === 'confirmed' && stage() !== 'confirmed' && !st.seenAt) st.seenAt = new Date().toISOString();
        st.status = { stage: d.stage, rows: d.rows, delivery: d.delivery || '', method: d.method || '' }; st.until = d.until || st.until;
        step = 0; render();
      } else step++;
      loadReceipt();
    }).catch(function () { step++; }).then(schedule);
  }

  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { clearTimeout(pollTimer); pollTimer = null; return; }
    step = 0; poll();
  });

  render();
  loadReceipt();
  tickTimer = setInterval(tick, 1000);
  schedule();
}


// ── Customer portal ──
// The customer portal (GET /portal/<pay token>). portalHtml_(data) returns the whole document: server-rendered, no script, no
// external assets. The CSP below allows inline styles only, so nothing a page could load can run.
// Bundled ahead of edge.js (after pay-page.js), so it is a plain top-level function in the same scope.
//
// data: { lang, customerName, lines: [{ product, paidTill, daysLeft, owes, payUrl }], owes, payments: [{ date, amount, method }],
//         payUrl, receiverName, receiverLast4 }
//   lines are the customer's active subscriptions only; payUrl on a line is the pay page for that line when it owes money.
//   payments are the customer's own payment rows, newest first; the portal never shows costs, suppliers or other customers.

var PORTAL_CSP_ = "default-src 'none'; style-src 'unsafe-inline'; img-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

var PORTAL_TEXT_ = {
  en: {
    title: 'Your subscriptions', lead: 'Hi {name}. Here is where your subscriptions stand.', owed: 'Amount owed', none: 'Nothing owed',
    next: 'Next renewal', noNext: 'No renewal date', pay: 'Pay now', payOpen: 'Open payment page', lines: 'Subscriptions',
    noLines: 'No active subscriptions.', paidTill: 'Paid till', st_active: 'Active', st_soon: 'Renews soon', st_expired: 'Expired',
    owesLine: 'Owes', history: 'Payment history', noHistory: 'No payments yet.', date: 'Date', amount: 'Amount', method: 'Method',
    trustTitle: 'Keep your money safe', trustPin: 'We never ask for your PIN or OTP.', trustOnly: 'Only enter your PIN inside the bKash app.',
    trustName: 'The confirm screen should show: {name}, number ending {last4}.', trustLast4: 'The confirm screen should show number ending {last4}.',
    footer: 'Read only. Use the payment link we sent you to pay.', pageTitle: 'Your subscriptions', noJs: 'This page needs no JavaScript.'
  },
  bn: {
    title: 'আপনার সাবস্ক্রিপশন', lead: 'হাই {name}। আপনার সাবস্ক্রিপশনের অবস্থা এখানে দেখুন।', owed: 'বাকি আছে', none: 'কোনো বাকি নেই',
    next: 'পরবর্তী রিনিউয়াল', noNext: 'রিনিউয়ালের তারিখ নেই', pay: 'এখন পেমেন্ট করুন', payOpen: 'পেমেন্ট পেজ খুলুন', lines: 'সাবস্ক্রিপশন',
    noLines: 'কোনো চালু সাবস্ক্রিপশন নেই।', paidTill: 'মেয়াদ', st_active: 'চালু', st_soon: 'শীঘ্রই রিনিউ', st_expired: 'মেয়াদ শেষ',
    owesLine: 'বাকি', history: 'পেমেন্টের ইতিহাস', noHistory: 'এখনও কোনো পেমেন্ট নেই।', date: 'তারিখ', amount: 'পরিমাণ', method: 'মাধ্যম',
    trustTitle: 'আপনার টাকা নিরাপদ রাখুন', trustPin: 'আমরা কখনো আপনার PIN বা OTP চাই না।', trustOnly: 'শুধু বিকাশ অ্যাপের ভেতরে PIN লিখুন।',
    trustName: 'কনফার্ম স্ক্রিনে দেখাবে: {name}, নম্বর শেষ {last4}।', trustLast4: 'কনফার্ম স্ক্রিনে দেখাবে নম্বর শেষ {last4}।',
    footer: 'শুধু দেখার জন্য। পেমেন্ট করতে আমাদের পাঠানো লিংক ব্যবহার করুন।', pageTitle: 'আপনার সাবস্ক্রিপশন', noJs: 'এই পেজে JavaScript লাগে না।'
  }
};

/** The status word and its colour class for one line. A line with no end date is shown as active. */
function portalStatus_(t, daysLeft) {
  if (daysLeft === null || daysLeft === undefined || daysLeft === '') return { word: t.st_active, cls: 'ok' };
  var d = Number(daysLeft);
  if (d < 0) return { word: t.st_expired, cls: 'bad' };
  if (d <= 3) return { word: t.st_soon, cls: 'warn' };
  return { word: t.st_active, cls: 'ok' };
}

function portalHtml_(data) {
  var lang = data.lang === 'bn' ? 'bn' : 'en', t = PORTAL_TEXT_[lang];
  var esc = function (s) { return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  // Raw on purpose: every caller escapes the whole line once, after filling it.
  var fill = function (s, vars) { return String(s).replace(/\{(\w+)\}/g, function (_, k) { return vars[k] === undefined ? '' : String(vars[k]); }); };
  var money = function (n) { return Core.reminders.money(Number(n) || 0); };
  var lines = data.lines || [], payments = data.payments || [];
  var owed = Math.round((Number(data.owes) || 0) * 100) / 100;
  var nextRenewal = lines.map(function (l) { return l.paidTill; }).filter(Boolean).sort()[0] || '';
  var name = data.customerName ? String(data.customerName) : '';
  var lineHtml = lines.length ? lines.map(function (l) {
    var st = portalStatus_(t, l.daysLeft);
    return '<li><div class="ln"><b>' + esc(l.product) + '</b><span class="st ' + st.cls + '">' + esc(st.word) + '</span></div>' +
      '<div class="meta">' + esc(t.paidTill) + ' ' + esc(l.paidTill || '-') + (Number(l.owes) > 0 ? ' · <span class="owe">' + esc(t.owesLine) + ' ' + esc(money(l.owes)) + '</span>' : '') +
      (Number(l.owes) > 0 && l.payUrl ? '<a class="mini" href="' + esc(l.payUrl) + '">' + esc(t.pay) + '</a>' : '') + '</div></li>';
  }).join('') : '<li class="empty">' + esc(t.noLines) + '</li>';
  var payHtml = payments.length ? '<table><thead><tr><th>' + esc(t.date) + '</th><th>' + esc(t.amount) + '</th><th>' + esc(t.method) + '</th></tr></thead><tbody>' +
    payments.map(function (p) { return '<tr><td>' + esc(p.date || '-') + '</td><td>' + esc(money(p.amount)) + '</td><td>' + esc(p.method || '-') + '</td></tr>'; }).join('') +
    '</tbody></table>' : '<p class="hint">' + esc(t.noHistory) + '</p>';
  var trust = '<p>' + esc(t.trustPin) + '</p><p>' + esc(t.trustOnly) + '</p>' +
    (data.receiverLast4 ? '<p>' + esc(data.receiverName ? fill(t.trustName, { name: data.receiverName, last4: data.receiverLast4 }) : fill(t.trustLast4, { last4: data.receiverLast4 })) + '</p>' : '');
  var payBtn = data.payUrl ? '<a class="btn" href="' + esc(data.payUrl) + '">' + esc(owed > 0 ? t.pay : t.payOpen) + '</a>' : '';
  var css =
    ':root{color-scheme:light dark;--bg:#f3f1ec;--card:#fff;--ink:#16171c;--mut:#5c6070;--line:#e4e2dc;--ok:#0f7b4a;--okbg:#e2f5ea;--warn:#8a5a06;--warnbg:#fff3d6;--bad:#b3261e;--badbg:#fdeceb;--b:#16171c;--bi:#fff;--soft:#f6f5f1;' +
    '--fd:"Iowan Old Style",Georgia,"Noto Serif Bengali",serif;--fb:-apple-system,"Segoe UI",Roboto,"Noto Sans Bengali",sans-serif}' +
    '@media(prefers-color-scheme:dark){:root{--bg:#0d0e12;--card:#16181f;--ink:#f1f1f4;--mut:#a0a4b2;--line:#2a2d38;--ok:#5ee0a0;--okbg:#0f2f21;--warn:#f5bd45;--warnbg:#33260a;--bad:#ff8a80;--badbg:#3a1614;--b:#f1f1f4;--bi:#16171c;--soft:#1d2029}}' +
    '*{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--bg);color:var(--ink);font-family:var(--fb);line-height:1.45;padding:14px 14px 28px;display:flex;justify-content:center}' +
    'main{width:100%;max-width:440px;display:grid;gap:12px;align-content:start}' +
    '.card{background:var(--card);border-radius:20px;box-shadow:0 1px 2px rgba(20,22,30,.06),0 14px 36px rgba(20,22,30,.1);overflow:hidden;padding:18px 18px 20px}' +
    'h1{margin:0;font-family:var(--fd);font-size:22px;font-weight:600;line-height:1.25;overflow-wrap:anywhere}h2{margin:0 0 8px;font-family:var(--fd);font-size:18px;font-weight:600}' +
    '.lead{margin:4px 0 0;font-size:14px;color:var(--mut);overflow-wrap:anywhere}.sum{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}' +
    '.sum div{background:var(--soft);border-radius:14px;padding:12px}.sum span{display:block;font-size:12px;color:var(--mut)}.sum b{display:block;font-size:20px;margin-top:2px;overflow-wrap:anywhere}' +
    'ul{list-style:none;margin:0;padding:0}li{padding:12px 0;border-top:1px solid var(--line)}li:first-child{border-top:0;padding-top:0}li.empty{color:var(--mut)}' +
    '.ln{display:flex;justify-content:space-between;gap:10px;align-items:center}.ln b{overflow-wrap:anywhere}.meta{margin-top:4px;font-size:13px;color:var(--mut);display:flex;gap:8px;align-items:center;flex-wrap:wrap}' +
    '.st{font-size:12px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap}.st.ok{background:var(--okbg);color:var(--ok)}.st.warn{background:var(--warnbg);color:var(--warn)}.st.bad{background:var(--badbg);color:var(--bad)}' +
    '.owe{color:var(--bad);font-weight:700}.mini{margin-left:auto;font-size:13px;font-weight:700;color:var(--b);text-decoration:underline;text-underline-offset:3px}' +
    '.btn{display:block;text-align:center;margin-top:14px;padding:14px 16px;border-radius:12px;background:var(--b);color:var(--bi);font-size:16px;font-weight:800;text-decoration:none;min-height:48px}' +
    'table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:8px 4px;border-top:1px solid var(--line)}th{font-size:12px;color:var(--mut);font-weight:600;border-top:0}' +
    '.hint{font-size:14px;color:var(--mut);margin:0}.trust{background:var(--soft);font-size:14px}.trust p{margin:0 0 6px}.trust p:last-child{margin:0}.trust h2{font-size:16px}' +
    '.foot{font-size:12px;color:var(--mut);text-align:center;padding:0 8px}' +
    '@media(prefers-reduced-motion:reduce){*{transition:none!important}}';
  return '<!DOCTYPE html><html lang="' + lang + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
    '<meta name="color-scheme" content="light dark"><meta name="robots" content="noindex"><title>' + esc(t.pageTitle) + '</title><style>' + css + '</style></head><body>' +
    '<main>' +
    '<section class="card"><h1>' + esc(t.title) + '</h1>' + (name ? '<p class="lead">' + esc(fill(t.lead, { name: name })) + '</p>' : '') +
    '<div class="sum"><div><span>' + esc(t.owed) + '</span><b>' + esc(owed > 0 ? money(owed) : t.none) + '</b></div>' +
    '<div><span>' + esc(t.next) + '</span><b>' + esc(nextRenewal || t.noNext) + '</b></div></div>' + payBtn + '</section>' +
    '<section class="card"><h2>' + esc(t.lines) + '</h2><ul>' + lineHtml + '</ul></section>' +
    '<section class="card"><h2>' + esc(t.history) + '</h2>' + payHtml + '</section>' +
    '<section class="card trust"><h2>' + esc(t.trustTitle) + '</h2>' + trust + '</section>' +
    '<p class="foot">' + esc(t.footer) + '</p>' +
    '</main></body></html>';
}


// ---- server (Edge Function) -------------------------------------------------
// Runs inside the bundled index.ts after the core modules and the Postgres adapter.
// `db` is { query(text, params) -> {rows}, transaction(fn) } (see the header in the built file).
var APP_TZ = 'Asia/Dhaka';

function today_() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: APP_TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(new Date());
}
function batchId_() { return crypto.randomUUID(); }

// Every write path takes this Postgres advisory lock inside its transaction, so writes run one at a time.
var WRITE_LOCK_ = 41001;
// actor (who made the call, see authenticate_) is set on the transaction, so change_log lines written through it name the caller.
async function locked_(db, fn, actor) {
  return db.transaction(async function (tx) {
    tx.actor = actor || '';
    await tx.query('SELECT pg_advisory_xact_lock($1)', [WRITE_LOCK_]);
    return fn(tx);
  });
}

// changed: true only when applyOps wrote a change_log batch, so the panel offers Undo only for a save Undo can reverse.
// batchId: that batch, the handle Undo takes (undo with batchId). Only a logged write has one. It is set here, after the plan's
// result, so a result key must never be named batchId (inventory batches use codeBatch).
async function commit_(db, plan, action, data, opts) {
  if (plan.errors && plan.errors.length) return { ok: false, error: plan.errors[0] };
  var logged = false, batch = batchId_();
  if (plan.ops && plan.ops.length) {
    var w = await Adapter.applyOps(db, plan.ops, { batchId: batch, action: action, log: !(opts && opts.log === false) });
    logged = !!(w && w.logged);
  }
  var out = Object.assign({}, data || plan.result || {}, { changed: logged });
  if (logged) out.batchId = batch; else delete out.batchId;
  return { ok: true, data: out };
}
var STALE_UNDO_ = 'Something else changed since. Open the history to undo it.';

// Payload of a pay-request action: a typed amount arrives as text. (api() already strips the client's clock and id generator.)
function clean_(p) {
  var o = Object.assign({}, p);
  if (typeof o.amount === 'string' && /^\s*\d+(\.\d+)?\s*$/.test(o.amount)) o.amount = Number(o.amount);
  return o;
}

// Open pay requests past their expiry become Expired and give their reserved code back. Computed on use, no scheduled job.
// Logged as autoExpire so Undo skips it. Returns the state to continue with (re-read when something changed).
async function sweepExpired_(tx, st) {
  var ops = Core.paylinks.planExpireRequests(st);
  if (!ops.length) return st;
  await Adapter.applyOps(tx, ops, { batchId: batchId_(), action: 'autoExpire', log: true });
  return Adapter.readState(tx, today_());
}
// Same sweep for a read: takes the write lock only when there is something to expire.
async function sweepForRead_(db, st) {
  if (!Core.paylinks.planExpireRequests(st).length) return st;
  return locked_(db, async function (tx) {
    return sweepExpired_(tx, await Adapter.readState(tx, today_()));
  });
}

// Stage a request shows. Paid, Cancelled and Expired come from its status (a no-product Paid request has no payment rows).
function requestStage_(rq, status, nowMs) {
  if (rq.Status === 'Paid') return 'confirmed';
  if (rq.Status === 'Cancelled') return 'cancelled';
  if (rq.Status === 'Expired') return 'expired';
  var exp = Date.parse(rq.Expires || '');
  if (rq.Status === 'Open' && isFinite(exp) && exp <= nowMs) return 'expired';
  return status.stage;
}

// Unofficial Bybit P2P ad list (USDT sold for BDT). Reachability from Supabase is unconfirmed; the manual rate is the fallback.
var BYBIT_P2P_URL = 'https://api2.bybit.com/fiat/otc/item/online';
async function fetchAds_() {
  var ctl = new AbortController();
  var timer = setTimeout(function () { ctl.abort(); }, 5000);
  try {
    var res = await fetch(BYBIT_P2P_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, signal: ctl.signal,
      body: JSON.stringify({ tokenId: 'USDT', currencyId: 'BDT', side: '1', size: '10', page: '1', amount: '' }) });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    var data = await res.json();
    if (!data || data.ret_code !== 0 || !data.result || !Array.isArray(data.result.items)) throw new Error('unexpected response');
    return data.result.items;
  } finally { clearTimeout(timer); }
}

// ---- money dashboard ----
// Planner internals (clock, id generator) must never come from the client.
function monthOf_(st, p) {
  var m = p && p.month !== undefined && p.month !== null && p.month !== '' ? p.month : st.today.slice(0, 7);
  var ok = typeof m === 'string' && /^\d{4}-(0[1-9]|1[0-2])$/.test(m);
  if (!ok) throw new Error('Month must look like 2026-10.');
  return m;
}
// A real calendar date, 'YYYY-MM-DD' (rejects 2026-02-31). Range for insights: both ends, from <= to, at most 24 months (731 days).
function dateOf_(v, what) {
  var ok = typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && Core.util.isoAddDays(v, 0) === v;
  if (!ok) throw new Error(what + ' must be a date like 2026-10-18.');
  return v;
}
function rangeOf_(st, p) {
  var has = function (k) { return p && p[k] !== undefined && p[k] !== null && p[k] !== ''; };
  if (!has('from') && !has('to')) return {};
  var to = has('to') ? dateOf_(p.to, 'To') : st.today;
  var from = has('from') ? dateOf_(p.from, 'From') : Core.util.addMonths(to, -12);
  if (from > to) throw new Error('From must not be after To.');
  if (Core.util.daysBetween(from, to) > 731) throw new Error('Pick a range of 24 months or less.');
  return { from: from, to: to };
}
// inbox payload: status ('all' by default), q (at most 80 characters) and days (1 to 365, default 90). Validated here; the window and the
// row limit are Core.views.inboxRows'.
var INBOX_STATUS_ = ['all', 'Pending', 'Review', 'Matched', 'Auto-matched', 'Ignored'];
function inboxOf_(st, p) {
  var has = function (k) { return p && p[k] !== undefined && p[k] !== null && p[k] !== ''; };
  var status = has('status') ? String(p.status) : 'all';
  if (INBOX_STATUS_.indexOf(status) < 0) throw new Error('Status must be all, Pending, Review, Matched, Auto-matched or Ignored.');
  var q = has('q') ? String(p.q).trim() : '';
  if (q.length > 80) throw new Error('Search must be 80 characters or fewer.');
  var days = 90;
  if (has('days')) {
    days = Number(p.days);
    if (!(Number.isInteger(days) && days >= 1 && days <= 365)) throw new Error('Days must be a whole number from 1 to 365.');
  }
  return Core.views.inboxRows(st, { status: status, q: q, days: days });
}
// reminderLog payload: status ('all' by default, or sent or skipped) and days (1 to 60, default 60). The window and the row limit are
// Core.views.reminderLog's.
var REMINDER_LOG_STATUS_ = ['all', 'sent', 'skipped'];
function reminderLogOf_(st, p) {
  var has = function (k) { return p && p[k] !== undefined && p[k] !== null && p[k] !== ''; };
  var status = has('status') ? String(p.status) : 'all';
  if (REMINDER_LOG_STATUS_.indexOf(status) < 0) throw new Error('Status must be all, sent or skipped.');
  var days = 60;
  if (has('days')) {
    days = Number(p.days);
    if (!(Number.isInteger(days) && days >= 1 && days <= 60)) throw new Error('Days must be a whole number from 1 to 60.');
  }
  return Core.views.reminderLog(st, { status: status, days: days });
}
// activity payload: limit (1 to 100 batches, default 100). The read takes the newest ACTIVITY_LINES_ change lines (Adapter.readRecentChangeLog);
// the batches are grouped and summarised by Core.views.activityBatches.
var ACTIVITY_LINES_ = 1500;
function activityLimit_(p) {
  var has = function (k) { return p && p[k] !== undefined && p[k] !== null && p[k] !== ''; };
  if (!has('limit')) return 100;
  var limit = Number(p.limit);
  if (!(Number.isInteger(limit) && limit >= 1 && limit <= 100)) throw new Error('Limit must be a whole number from 1 to 100.');
  return limit;
}
function layoutOf_(st) {
  var known = {};
  Core.money.WIDGETS.forEach(function (w) { known[w.id] = true; });
  var out = [];
  String((st.settings && st.settings.money_layout) || '').split(',').forEach(function (x) {
    x = x.trim();
    if (known[x] === true && out.indexOf(x) < 0) out.push(x);
  });
  return out.length ? out : Core.money.DEFAULT_LAYOUT.slice();
}
function moneyExport_(st, p) {
  var tab = p && p.tab, month = monthOf_(st, p), csv;
  if (tab === 'overview') {
    var o = Core.money.overview(st, month), rows = [];
    rows.push({ Section: 'Summary', Item: 'Net', Value: o.net });
    rows.push({ Section: 'Summary', Item: 'Previous month net', Value: o.prevNet });
    rows.push({ Section: 'Summary', Item: 'In', Value: o.in });
    rows.push({ Section: 'Summary', Item: 'Out', Value: o.out });
    o.series.forEach(function (x) { rows.push({ Section: 'Trend ' + x.month, Item: 'Net', Value: x.net }); });
    o.expensesByType.forEach(function (x) { rows.push({ Section: 'Expenses', Item: x.category, Value: x.amount }); });
    o.products.forEach(function (x) { rows.push({ Section: 'Profit by product', Item: x.name, Value: x.profit }); });
    o.accounts.forEach(function (x) { rows.push({ Section: 'Profit by account', Item: x.label, Value: x.profit }); });
    o.dues.buckets.forEach(function (x) { rows.push({ Section: 'Dues', Item: x.label + ' days late', Value: x.amount }); });
    csv = Core.exporter.toCsv(Core.exporter.safeRows(rows), ['Section', 'Item', 'Value']);
  } else if (tab === 'book') {
    var b = Core.views.bookData(st, month);
    csv = Core.exporter.toCsv(Core.exporter.safeRows(b.entries.map(function (e) {
      return { Date: e.date, Type: e.kind === 'in' ? 'In' : 'Out', Description: e.label, Method: e.method, Amount: e.amount, Balance: e.balance, Ref: e.id };
    })), ['Date', 'Type', 'Description', 'Method', 'Amount', 'Balance', 'Ref']);
  } else if (tab === 'cash') {
    csv = Core.exporter.toCsv(Core.exporter.safeRows(Core.money.overview(st, month).cash.map(function (c) {
      return { Method: c.method, In: c.in, Out: c.out, Balance: c.balance };
    })), ['Method', 'In', 'Out', 'Balance']);
  } else {
    throw new Error('Export tab must be overview, book or cash.');
  }
  // Cash figures are all time, so the cash file carries no month.
  return { filename: 'sales-tracker-' + tab + '-' + (tab === 'cash' ? 'all-time' : month) + '.csv', csv: csv };
}

// ---- table-scoped reads ----
// NEEDS_[action] lists the tabs (Adapter.TABS names) an action's view or planner touches; Settings is always loaded. An action
// with no entry reads every table, which is the safe default. A table left out is absent from the state, so a view that quietly
// needs it would give wrong numbers, not an error: derive an entry from the Core function AND everything it calls, and keep it in
// step with test/scoped-state.test.js, which runs each declared action over a rich seed with all tables and with only these.
// Ids on ops (Core.ids.IdGen) count existing rows of many tables, but a read never returns them, so they are not listed for reads.
var NEEDS_ = {
  // overview: bookData (Payments, Purchases, Expenses, names from Customers), profit splits and goal profit (Sales_Log, Product_Catalog,
  // cost via Suppliers and Live_Rates), dues buckets, top customers, forecast, accounts for the account split, Goals and Budgets.
  moneyOverview: ['Customers', 'Sales_Log', 'Payments', 'Expenses', 'Purchases', 'Accounts', 'Product_Catalog', 'Suppliers', 'Live_Rates', 'Goals', 'Budgets'],
  // overview / book / cash tabs: the overview set without the goals and budgets, which an export never shows.
  moneyExport: ['Customers', 'Sales_Log', 'Payments', 'Expenses', 'Purchases', 'Accounts', 'Product_Catalog', 'Suppliers', 'Live_Rates'],
  // init = lookups + home.
  init: ['Customers', 'Sales_Log', 'Payments', 'Accounts', 'Product_Catalog', 'Code_Inventory', 'Payment_Inbox', 'Reminders_Log', 'Pay_Requests',
    'Suppliers', 'Live_Rates', 'Wallets', 'Deliveries', 'Profit_Snapshots', 'Expenses', 'Purchases', 'Budgets'],
  // homeData: sales, customers, products, payments (paid map, Auto list), accounts (hidden ones), inbox, Reminders_Log (planReminders), and
  // matching.whyNotAuto, which plans each unmatched message: Pay_Requests and Code_Inventory for a pay-link reference, Sales_Log and Accounts
  // for a line reference.
  // Also Deliveries and Budgets (with Expenses and Purchases for the budget spend) for the Today needs-attention counts.
  // stockAlerts (home.stock) reads Accounts and Sales_Log (free seats), Code_Inventory (unsold codes) and Product_Catalog (delivers-as).
  home: ['Customers', 'Sales_Log', 'Payments', 'Accounts', 'Product_Catalog', 'Code_Inventory', 'Payment_Inbox', 'Reminders_Log', 'Pay_Requests', 'Deliveries', 'Expenses', 'Purchases', 'Budgets'],
  // lookups: products, accounts (free seats from Sales_Log), unsold Code_Inventory and batches, customers with balances (Payments),
  // Suppliers with their products, the rate (Live_Rates), Wallets, and the pending Deliveries count.
  lookups: ['Customers', 'Sales_Log', 'Payments', 'Accounts', 'Product_Catalog', 'Code_Inventory', 'Suppliers', 'Live_Rates', 'Wallets', 'Deliveries'],
  // customerData: the customer, their sales (prices from Product_Catalog), their payments, balances.
  // with withLocks (the customer read) the payment locks read Pay_Requests.
  customer: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog', 'Pay_Requests'],
  // Looks up the sale, then customerData for the kind, then buildMessage (customer, product, paid map, settings).
  reminderMessage: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog'],
  // duesList: sales with balances, customers with credit.
  dues: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog'],
  // accountsOverview: accounts and their sales (free seats, collected), costs of ended lines via Suppliers and Live_Rates.
  accounts: ['Accounts', 'Sales_Log', 'Customers', 'Product_Catalog', 'Payments', 'Suppliers', 'Live_Rates'],
  // Core.paylinks.list: one row per live line with its intent, the inbox rows that match its reference and its recorded payments.
  payLinks: ['Pay_Intents', 'Accounts', 'Product_Catalog', 'Customers', 'Payments', 'Sales_Log', 'Payment_Inbox'],
  // sweepForRead_ (Pay_Requests, Code_Inventory), requestStatus (Pay_Intents, Payments, Payment_Inbox), names (Customers, Product_Catalog),
  // the delivery per request, and delivery.confirmable (Product_Catalog, Code_Inventory, Sales_Log, Customers). A sweep re-reads everything.
  payRequests: ['Pay_Requests', 'Code_Inventory', 'Pay_Intents', 'Payments', 'Payment_Inbox', 'Customers', 'Product_Catalog', 'Deliveries', 'Sales_Log'],
  // sweepForRead_ (Pay_Requests, Code_Inventory) then listDeliveries: names (Customers, Product_Catalog), the request and sale for the order link.
  deliveries: ['Deliveries', 'Customers', 'Product_Catalog', 'Pay_Requests', 'Sales_Log', 'Code_Inventory'],
  // bookData: Payments, Purchases, Expenses, names from Customers (index also builds the Product_Catalog map).
  // with withLocks (the book read) the payment locks read Pay_Requests.
  book: ['Payments', 'Purchases', 'Expenses', 'Customers', 'Product_Catalog', 'Pay_Requests'],
  // entryDetail: the row of its kind, then its customer, sale, inbox message or wallet.
  entry: ['Payments', 'Expenses', 'Purchases', 'Customers', 'Sales_Log', 'Payment_Inbox', 'Wallets'],
  // productList: the product's accounts and their active sales (free seats read Sales_Log).
  product: ['Accounts', 'Sales_Log', 'Customers', 'Product_Catalog', 'Payments'],
  // profitByFamily: sales by category, cost via Suppliers and Live_Rates (USDT).
  profit: ['Sales_Log', 'Product_Catalog', 'Customers', 'Payments', 'Suppliers', 'Live_Rates'],
  // Core.importer.review: staged rows (Import_Rows), the matches against products and accounts (Accounts, Product_Catalog), customers, the
  // active line of an account for a customer and what it has paid (Sales_Log, Payments), codes already in stock and inbox transactions.
  importReview: ['Import_Rows', 'Customers', 'Sales_Log', 'Payments', 'Accounts', 'Product_Catalog', 'Code_Inventory', 'Payment_Inbox'],
  // Core.accrual.monthly: sales and their coverage (Sales_Log, Product_Catalog), accounts and their purchases (Accounts, Purchases), cash by month
  // (Payments), and the fallback seat cost of a sale with no purchase via Suppliers and Live_Rates (USDT).
  profitMonthly: ['Sales_Log', 'Product_Catalog', 'Accounts', 'Purchases', 'Payments', 'Suppliers', 'Live_Rates'],
  // matching.suggest: the inbox row, customers, product letters, the line behind the reference (Sales_Log, Accounts), last payment dates.
  suggestCustomers: ['Payment_Inbox', 'Customers', 'Product_Catalog', 'Sales_Log', 'Accounts', 'Payments'],
  // Core.money.insights: sales (billed, renewals, retention, forecast, owed), payments (collected, paid map), customers (names), products
  // (category, delivers-as), cost via Suppliers and Live_Rates, and Accounts (a deleted account's lines are not live lines).
  insights: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog', 'Accounts', 'Suppliers', 'Live_Rates'],
  // Core.views.inboxRows: the inbox rows, and the Payments whose transaction ids mark a Matched message Auto-matched. No names are shown.
  inbox: ['Payment_Inbox', 'Payments'],
  // Core.views.reminderLog: the Reminders_Log rows (sent and skipped), the customer name, and the product and ref of the sale (Sales_Log, Product_Catalog).
  reminderLog: ['Reminders_Log', 'Customers', 'Sales_Log', 'Product_Catalog'],
  // Core.views.activityBatches reads Change_Log only (Adapter.readRecentChangeLog), which is not a state table, so no state table is loaded.
  // An empty list is the declaration: readState then loads Settings alone.
  activity: [],
  // Hot writes. A planner draws new ids from Core.ids.IdGen, which counts existing rows (payment ids: Payments; sale ids and line codes:
  // Sales_Log; customer ids: Customers), so each entry also lists the tables whose counter that planner uses.
  // pay: customer, trx check and balances (Payments, Sales_Log, Product_Catalog), new payment ids.
  pay: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog'],
  // newSale: product, customer (or a new id), seat check (Accounts, Sales_Log), the code (Code_Inventory), sale and line ids, paid-now payment id.
  newSale: ['Customers', 'Sales_Log', 'Payments', 'Product_Catalog', 'Accounts', 'Code_Inventory'],
  // renew: the line (Sales_Log), product, account, credit and trx (Payments), new sale and payment ids.
  renew: ['Sales_Log', 'Product_Catalog', 'Accounts', 'Payments'],
  // customSale: no product, account or code; the customer (or a new id), trx check (Payments) and the sale and payment ids.
  customSale: ['Customers', 'Sales_Log', 'Payments'],
  // Migration staging writes. Stage, add, delete and status touch only the staged rows.
  importStage: ['Import_Rows'],
  // jobs: job_runs (read in the action) and the settings the relay flag comes from; no state table.
  jobs: [],
  importAdd: ['Import_Rows'],
  importDelete: ['Import_Rows'],
  importStatus: ['Import_Rows'],
  // importEdit: the row, plus the ids a chosen match must name (customers, accounts, sales, products).
  importEdit: ['Import_Rows', 'Customers', 'Accounts', 'Sales_Log', 'Product_Catalog'],
  // importApply: staged rows, the matches review reads, and the tables the planners append to and count for ids (Purchases for the account cost).
  importApply: ['Import_Rows', 'Customers', 'Sales_Log', 'Payments', 'Accounts', 'Product_Catalog', 'Code_Inventory', 'Payment_Inbox', 'Purchases'],
  // orders (read): the order rows, names, the product, and each pay link's status and URL (sweepForRead_ reads Pay_Requests and Code_Inventory).
  orders: ['Orders', 'Customers', 'Product_Catalog', 'Pay_Requests', 'Code_Inventory'],
  // createOrder: the order, request and sale ids (Core.ids.IdGen counts every table below), the customer, the product, the pay request's
  // reference and the sweep of expired requests (Pay_Requests, Code_Inventory).
  createOrder: ['Orders', 'Customers', 'Product_Catalog', 'Pay_Requests', 'Sales_Log', 'Payments', 'Code_Inventory', 'Deliveries'],
  // orderStatus: the order, its pay link, and the code a cancelled link gives back (releaseOps). The sweep reads the same tables.
  orderStatus: ['Orders', 'Pay_Requests', 'Code_Inventory'],
  // fulfilOrder: the order and its pay link, the product, the customer and sale ids, the account or code planNewSale picks from, the
  // delivery id, and the payments the link recorded (attached to the sale).
  fulfilOrder: ['Orders', 'Pay_Requests', 'Product_Catalog', 'Customers', 'Sales_Log', 'Payments', 'Accounts', 'Code_Inventory', 'Deliveries'],
  // editProductPublic: the product and the other products' web addresses (slug uniqueness).
  editProductPublic: ['Product_Catalog']
};

